('🌟 Hunter Exam: Decode the Message', E'A secret message has been encoded. Each letter is shifted by a key (Caesar cipher). Write functions to encode and decode messages with any shift key.\n\n---EXAMPLES---\nencode("HELLO", 3) → "KHOOR"\ndecode("KHOOR", 3) → "HELLO"\nencode("Attack at dawn", 5) → "Fyyfhp fy ifbs"\n\n---STARTER---\nfunction encode(message, key) {\n  // Shift each letter by key positions\n}\n\nfunction decode(message, key) {\n  // Reverse the shift\n}\n\nconsole.log(encode("HELLO", 3)); // KHOOR\nconsole.log(decode("KHOOR", 3)); // HELLO\nconsole.log(encode("Attack at dawn", 5));', 'easy', 30, 2, 'special'),

('🌟 Dungeon Map Generator', E'Generate a random dungeon map as a 2D grid. Place rooms (R), corridors (.), walls (#), and an entrance (E) and exit (X). Ensure there is always a valid path from E to X.\n\n---EXAMPLES---\nInput: generateDungeon(8, 8)\nOutput:\n########\n#E..#..#\n#.#...R#\n#.###..#\n#R....R#\n#.##.#.#\n#....#X#\n########\n\n---STARTER---\nfunction generateDungeon(width, height) {\n  // Create a 2D grid\n  // Place walls, rooms, corridors\n  // Ensure path from E to X exists\n  // Return the grid as a string\n}\n\nfunction hasPath(grid, start, end) {\n  // BFS/DFS to verify path exists\n}\n\nconsole.log(generateDungeon(8, 8));', 'medium', 50, 3, 'special'),

('🌟 System Window: JSON Parser', E'Build a JSON parser from scratch. Parse a JSON string into a JavaScript value WITHOUT using JSON.parse().\n\n---EXAMPLES---\nmyParse(''{"name":"Jin-Woo","level":100}'') → { name: "Jin-Woo", level: 100 }\nmyParse(''[1, "two", true, null]'') → [1, "two", true, null]\nmyParse(''"hello"'') → "hello"\nmyParse(''42'') → 42\n\n---STARTER---\nfunction myParse(jsonStr) {\n  let pos = 0;\n\n  function parseValue() {\n    skipWhitespace();\n    // Determine type and parse accordingly\n  }\n\n  function parseString() {\n    // Parse "..." string\n  }\n\n  function parseNumber() {\n    // Parse number\n  }\n\n  function parseObject() {\n    // Parse { key: value, ... }\n  }\n\n  function parseArray() {\n    // Parse [ value, ... ]\n  }\n\n  function skipWhitespace() {\n    while (pos < jsonStr.length && " \\t\\n\\r".includes(jsonStr[pos])) pos++;\n  }\n\n  return parseValue();\n}\n\nconsole.log(myParse(''{"name":"Jin-Woo","level":100}''));\nconsole.log(myParse(''[1,"two",true,null]''));', 'hard', 70, 4, 'special'),

('🌟 Shadow Exchange: Rate Limiter', E'Implement a rate limiter using the Token Bucket algorithm. It should allow burst traffic up to a limit and refill tokens at a steady rate.\n\n---EXAMPLES---\nconst limiter = new RateLimiter({ maxTokens: 5, refillRate: 1, refillInterval: 1000 });\nlimiter.tryAcquire() → true  (4 tokens left)\nlimiter.tryAcquire() → true  (3 tokens left)\n// ... exhaust all 5\nlimiter.tryAcquire() → false (rate limited)\n// After 1 second, 1 token refilled\nlimiter.tryAcquire() → true\n\n---STARTER---\nclass RateLimiter {\n  constructor({ maxTokens, refillRate, refillInterval }) {\n    this.maxTokens = maxTokens;\n    this.tokens = maxTokens;\n    this.refillRate = refillRate;\n    this.refillInterval = refillInterval;\n    this.lastRefill = Date.now();\n  }\n\n  tryAcquire() {\n    this._refill();\n    // Check if token available, consume one\n  }\n\n  _refill() {\n    // Add tokens based on elapsed time\n  }\n\n  getTokens() {\n    this._refill();\n    return this.tokens;\n  }\n}\n\nconst limiter = new RateLimiter({ maxTokens: 5, refillRate: 1, refillInterval: 1000 });\nconsole.log(limiter.tryAcquire()); // true\nconsole.log(limiter.tryAcquire()); // true\nconsole.log(limiter.getTokens()); // 3', 'medium', 50, 3, 'special'),

('🌟 Monarch''s Memory: Memoization Engine', E'Build a powerful memoization utility that caches function results. Support TTL (time-to-live), max cache size with LRU eviction, and cache statistics.\n\n---EXAMPLES---\nconst add = memoize((a, b) => a + b, { maxSize: 3, ttl: 5000 });\nadd(1, 2) → 3 (computed)\nadd(1, 2) → 3 (cached)\nadd(3, 4) → 7 (computed)\nadd.stats() → { hits: 1, misses: 2, size: 2 }\n\n---STARTER---\nfunction memoize(fn, options = {}) {\n  const { maxSize = 100, ttl = Infinity } = options;\n  // Your cache implementation here\n\n  function memoized(...args) {\n    // Check cache, compute if needed, manage eviction\n  }\n\n  memoized.stats = () => {\n    // Return { hits, misses, size }\n  };\n\n  memoized.clear = () => {\n    // Clear the cache\n  };\n\n  return memoized;\n}\n\nconst add = memoize((a, b) => a + b, { maxSize: 3 });\nconsole.log(add(1, 2)); // 3 (computed)\nconsole.log(add(1, 2)); // 3 (cached)\nconsole.log(add(3, 4)); // 7 (computed)\nconsole.log(add.stats()); // { hits: 1, misses: 2, size: 2 }', 'medium', 55, 3, 'special'),

('🌟 Arise: Code Transpiler', E'Build a mini code transpiler that converts a simplified pseudo-language into JavaScript. Support variable declarations, if/else, loops, and functions.\n\n---EXAMPLES---\nInput:\n  let x = 10\n  if x > 5 then\n    print "big"\n  else\n    print "small"\n  end\n\nOutput (JS):\n  let x = 10;\n  if (x > 5) {\n    console.log("big");\n  } else {\n    console.log("small");\n  }\n\n---STARTER---\nfunction transpile(pseudoCode) {\n  const lines = pseudoCode.trim().split("\\n");\n  let output = [];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i].trim();\n    // Transform each line to valid JavaScript\n  }\n\n  return output.join("\\n");\n}\n\nconst code = `let x = 10\nif x > 5 then\n  print "big"\nelse\n  print "small"\nend`;\n\nconsole.log(transpile(code));', 'hard', 80, 5, 'special');
